    ('019a0000-0000-7000-8000-000000000102', '019a0000-0000-7000-8000-000000000902', '019a0000-0000-7000-8000-000000000808', '019a0000-0000-7000-8000-000000000503', 'attended', 'Two benign nevi on the left forearm, unchanged since the last screening. Sunscreen advised; next screening in 12 months.', '2026-11-09T15:42:00Z', '2026-11-09T15:42:00Z'),
    ('019a0000-0000-7000-8000-000000000103', '019a0000-0000-7000-8000-000000000903', '019a0000-0000-7000-8000-000000000810', '019a0000-0000-7000-8000-000000000507', 'attended', 'BMI 31.2. Agreed on a 1800 kcal plan and three walks a week. Fasting glucose ordered; review in 4 weeks.', '2026-11-11T16:48:00Z', '2026-11-12T13:05:00Z'),
    ('019a0000-0000-7000-8000-000000000101', '019a0000-0000-7000-8000-000000000904', '019a0000-0000-7000-8000-000000000814', '019a0000-0000-7000-8000-000000000502', 'attended', 'Home visit after knee surgery. Wound clean, no signs of infection. Stitches out in 5 days.', '2026-09-03T18:10:00Z', '2026-09-03T18:10:00Z'),
    ('019a0000-0000-7000-8000-000000000101', '019a0000-0000-7000-8000-000000000905', '019a0000-0000-7000-8000-000000000815', '019a0000-0000-7000-8000-000000000508', 'attended', 'Seasonal allergic rhinitis. Loratadine 10 mg daily for 14 days; return if fever appears.', '2026-08-18T15:38:00Z', '2026-08-18T15:38:00Z')
